# $FrankenrouterDir is a working directory you create yourself (it holds
# frankenrouter's config file(s), not an installer output), so it keeps a
# generic default above. But unlike a fresh install, that directory won't
# exist until you create it, so we still need to check for it. Unlike the
# addons above, frankenrouter.py itself is always started (both
# start_router_master.ps1 and start_router_slave.ps1), so this check is
# unconditional.
if (-not (Test-Path $FrankenrouterDir -PathType Container)) {
    Show-ErrorAndExit "`$FrankenrouterDir not found: $FrankenrouterDir`nCreate this directory and place your frankenrouter config file(s) in it (one for the master router, one for the slave router, if you run both), then add --config-file=<name> to `$FrankenrouterMasterOptions and/or `$FrankenrouterSlaveOptions in $OverrideFile. See psxhacks-start-override-EXAMPLE.ps1 for an example."
}

# $FrankenusbDir is a working directory you create yourself (it holds
# frankenusb's config file, not an installer output), so it keeps a
# generic default above, but only needs to exist if FrankenUSB is enabled.
if ($StartFrankenusb) {
    if (-not (Test-Path $FrankenusbDir -PathType Container)) {
        Show-ErrorAndExit "`$FrankenusbDir not found: $FrankenusbDir`nCreate this directory and place your frankenusb config file in it (frankenusb.conf by default; if you use a different name, add it to `$FrankenusbOptions in $OverrideFile). See psxhacks-start-override-EXAMPLE.ps1 for an example."
    }
}

# Flavor settings override both defaults and machine-specific overrides.
if (Test-Path $FlavorFile) { . $FlavorFile }

if ($StartPsxNetVatsim) { $RadioApp = "PSX.NET.VATSIM" }
